#!/bin/bash
# Generates the Nova & Juno reference assets (character sheets, vehicles, homes) from crops of the concept boards in images/src/
cd "$(dirname "$0")/.."
SRC=images/src
NT="Absolutely no text, labels, captions or watermarks anywhere in the image."
SHEET="Character reference sheet on a plain dark charcoal studio background, soft cinematic key light, photorealistic, four panels side by side: (1) head-and-shoulders front view, neutral friendly expression, (2) head-and-shoulders three-quarter view, smiling, (3) head-and-shoulders side profile, (4) full-body standing front view showing her whole outfit and shoes. Same woman in every panel - match her face, hair, freckles and skin exactly to the reference photos. $NT"
N="Nova: woman around 30, dark brown wavy hair in a loose messy updo with loose strands framing her face, blue-grey eyes, light freckles, warm natural look, layered delicate necklaces with a small round pendant, stacked thin dark bead bracelets, a slouchy dark charcoal knit cardigan over a dark camisole, faded ripped light-wash jeans, worn dark ankle boots."
J="Juno: woman around 30, tousled platinum-blonde chin-length shaggy bob, hazel-green eyes, freckles, mischievous grin, a detailed black-and-grey tattoo sleeve on her right arm (compass, clock and mechanical gears), dark olive tank top, faded charcoal work overalls with one strap down, a pair of brass-rimmed welding goggles pushed up in her hair, scuffed steel-toe work boots."
g(){ n=$1; p=$2; shift 2; python tools/gen_image.py "$n" "$p" --ref "$@" > "logs_$n.txt" 2>&1 & }
g nova_ref "$SHEET $N" $SRC/nova_face_source.png $SRC/nova_shots_source.png
g juno_ref "$SHEET $J" $SRC/juno_face_source.png $SRC/juno_shots_source.png
g nova_car_ref "Vehicle reference sheet, photorealistic, plain dark studio floor with soft reflections: Nova's car, the exact silver-white electric hybrid sports coupe from the reference image (low sleek fastback, thin full-width light bar across the nose, glowing blue LED accents, black aero wheels with blue accents, no badges). Three views side by side: front three-quarter, side profile, rear three-quarter. Match the design exactly. $NT" $SRC/nova_car_source.png
g juno_trike_ref "Vehicle reference sheet, photorealistic, plain dark studio floor with soft reflections: Juno's ride, the exact custom hand-built three-wheeler from the reference image (two fat rear wheels, one front wheel on a long raked fork, exposed rebuilt V-twin hybrid engine and pipes, tan-brown leather seat, matte black frame with hand-welded seams, twin round headlights). Three views side by side: front three-quarter, side profile, rear three-quarter. Match the design exactly. $NT" $SRC/juno_trike_source.png
g nova_home_ref "Photorealistic architectural reference: Nova's modern hillside home at blue-hour dusk - two-story glass and dark-stone minimalist house, floor-to-ceiling windows glowing warm inside, cantilevered upper floor, infinity pool lit blue, desert-garden landscaping, panoramic view of distant city lights below. Match the reference house exactly. Wide establishing shot. $NT" $SRC/nova_home_source.png $SRC/nova_interiors_source.png
g juno_loft_ref "Photorealistic architectural reference: Juno's garage loft workshop at dusk - a weathered dark-wood and corrugated-metal two-story building at the edge of the high desert with pines, a huge open garage door on the ground floor spilling warm light over a cluttered workshop (red tool chests, half-built engines, motorcycles, string lights, welding gear), an exterior steel staircase up to a lived-in loft apartment with big warm-lit windows and a balcony. Match the reference building exactly. Wide establishing shot. $NT" $SRC/juno_loft_source.png $SRC/juno_interiors_source.png
wait; cat logs_*.txt; rm logs_*.txt
